import{_ as t,o as i,c as o,a2 as h}from"./chunks/framework.O93z6AWZ.js";const d=JSON.parse('{"title":"Lab: Suy tim cấp tốc","description":"","frontmatter":{"title":"Lab: Suy tim cấp tốc"},"headers":[],"relativePath":"du_an/suy_tim_risk_dxai_lab.md","filePath":"du_an/suy_tim_risk_dxai_lab.md"}'),a={name:"du_an/suy_tim_risk_dxai_lab.md"};function e(c,n,r,l,g,s){return i(),o("div",null,[...n[0]||(n[0]=[h('<h1 id="huong-dan-thuc-hanh-du-bao-tu-vong-suy-tim-ban-cap-toc-5-buoi" tabindex="-1">Hướng dẫn thực hành: Dự báo tử vong Suy tim (Bản Cấp Tốc 5 buổi) <a class="header-anchor" href="#huong-dan-thuc-hanh-du-bao-tu-vong-suy-tim-ban-cap-toc-5-buoi" aria-label="Permalink to &quot;Hướng dẫn thực hành: Dự báo tử vong Suy tim (Bản Cấp Tốc 5 buổi)&quot;">​</a></h1><p>Tài liệu này cung cấp <strong>đề bài và hướng dẫn thực hành</strong> (Lab Manual) cho đồ án <a href="/hmyt-book/du_an/suy_tim_risk_dxai">3.4 Suy tim cấp tốc</a>. Mục tiêu của bài thực hành là giúp sinh viên tự tay hoàn thành một pipeline Học máy y tế đầy đủ (từ EDA, Baseline, Cải tiến, XAI đến Báo cáo) trong thời gian <strong>ngắn nhất có thể</strong> (10–15 giờ làm việc).</p><div class="warning custom-block"><p class="custom-block-title">Zero-Code Policy</p><p>Mã nguồn chi tiết của bài thực hành này được giảng viên giữ <strong>Private</strong>. Sinh viên cần tự vận dụng các thư viện như <code>pandas</code>, <code>scikit-learn</code>, <code>imbalanced-learn</code>, và <code>shap</code> để hoàn thành các yêu cầu dưới đây.</p></div><div class="danger custom-block"><p class="custom-block-title">⚠️ Case Study minh họa của Chương 2 KHÔNG phải bài nộp hợp lệ</p><p>Chương 2 có 1 <a href="/hmyt-book/labs_chuyen_de/ch02_suy_tim_risk_dxai">case study minh họa đầy đủ, công khai</a> dùng đúng bộ dữ liệu này để dạy lý thuyết. Notebook đó phục vụ mục đích giảng dạy — copy nguyên bản để nộp cho đồ án này bị coi là không hoàn thành yêu cầu Zero-Code Policy ở trên.</p></div><hr><h2 id="_0-chuan-bi-moi-truong-du-lieu" tabindex="-1">0. Chuẩn bị Môi trường &amp; Dữ liệu <a class="header-anchor" href="#_0-chuan-bi-moi-truong-du-lieu" aria-label="Permalink to &quot;0. Chuẩn bị Môi trường &amp; Dữ liệu&quot;">​</a></h2><ol><li><strong>Khởi tạo dự án:</strong> Tạo thư mục <code>suy_tim_risk_dxai</code> và thiết lập môi trường ảo (<code>venv</code>).</li><li><strong>Cài đặt thư viện:</strong> Cài đặt các thư viện lõi: <code>pandas</code>, <code>numpy</code>, <code>scikit-learn</code>, <code>imbalanced-learn</code>, <code>shap</code>, <code>matplotlib</code>, <code>seaborn</code>, <code>jupyter</code>.</li><li><strong>Tải dữ liệu:</strong> Tải bộ dữ liệu công khai (không cần xin quyền): <ul><li>Nguồn Kaggle: <a href="https://www.kaggle.com/datasets/andrewmvd/heart-failure-clinical-data" target="_blank" rel="noreferrer">Heart Failure Clinical Data</a></li><li>Hoặc nguồn UCI: <a href="https://archive.ics.uci.edu/dataset/519/heart+failure+clinical+records" target="_blank" rel="noreferrer">Heart Failure Clinical Records</a></li><li>Lưu file dưới dạng <code>data/heart_failure_clinical_records.csv</code>. Bộ dữ liệu gồm 299 dòng (tương ứng 299 bệnh nhân độc lập) và 13 đặc trưng. Nhãn dự đoán là cột <code>DEATH_EVENT</code>.</li></ul></li></ol><hr><h2 id="buoi-1-kham-pha-chuan-bi-du-lieu-eda-preprocessing" tabindex="-1">Buổi 1: Khám phá &amp; Chuẩn bị dữ liệu (EDA &amp; Preprocessing) <a class="header-anchor" href="#buoi-1-kham-pha-chuan-bi-du-lieu-eda-preprocessing" aria-label="Permalink to &quot;Buổi 1: Khám phá &amp; Chuẩn bị dữ liệu (EDA &amp; Preprocessing)&quot;">​</a></h2><p><strong>Mục tiêu:</strong> Hiểu rõ dữ liệu lâm sàng và thiết lập dữ liệu an toàn để huấn luyện (tránh Data Leakage).</p><ul><li><strong>Nhiệm vụ 1 (EDA):</strong> Tải dữ liệu bằng <code>pandas</code>. Kiểm tra giá trị khuyết thiếu. Phân tích tỷ lệ nhãn <code>DEATH_EVENT</code> để xác định xem dữ liệu có bị mất cân bằng hay không. Vẽ biểu đồ phân bố và ma trận tương quan (Correlation Heatmap).</li><li><strong>Nhiệm vụ 2 (Data Split):</strong> Phân chia tập huấn luyện và kiểm thử (Train/Test Split) theo tỷ lệ 80/20. Chú ý giữ đúng tỷ lệ phân bố nhãn (stratify) trên cả hai tập.</li><li><strong>Nhiệm vụ 3 (Chuẩn hóa):</strong> Sử dụng <code>StandardScaler</code> để chuẩn hóa các đặc trưng số. <ul><li><em>Câu hỏi tư duy:</em> Tại sao bạn chỉ được gọi hàm <code>fit</code> trên tập Train mà không được gọi trên tập Test?</li></ul></li></ul><blockquote><p><strong>Sản phẩm bàn giao:</strong> File <code>1_eda.ipynb</code>.</p></blockquote><hr><h2 id="buoi-2-tai-lap-y-van-goc-baseline-model" tabindex="-1">Buổi 2: Tái lập Y văn gốc (Baseline Model) <a class="header-anchor" href="#buoi-2-tai-lap-y-van-goc-baseline-model" aria-label="Permalink to &quot;Buổi 2: Tái lập Y văn gốc (Baseline Model)&quot;">​</a></h2><p><strong>Mục tiêu:</strong> Xây dựng mô hình phân loại cơ bản và tái lập kết quả của bài báo gốc <code>chicco2020machine</code>.</p><ul><li><strong>Nhiệm vụ 1:</strong> Huấn luyện mô hình <strong>Logistic Regression</strong> (như một mô hình tuyến tính cơ bản để làm hệ quy chiếu).</li><li><strong>Nhiệm vụ 2:</strong> Huấn luyện mô hình <strong>Random Forest Classifier</strong> (đúng như phương pháp của bài báo gốc).</li><li><strong>Nhiệm vụ 3:</strong> Đo lường các chỉ số hiệu năng: <code>Accuracy</code>, <code>MCC</code> (Matthews Correlation Coefficient), và <code>F1-score</code> trên tập Test.</li><li><strong>Nhiệm vụ 4:</strong> Đối chiếu với y văn. Nhóm tác giả Chicco đạt được <strong>Accuracy 74.0%</strong> và <strong>MCC 0.384</strong>. Mô hình Random Forest của bạn có tiệm cận mức này không?</li></ul><blockquote><p><strong>Sản phẩm bàn giao:</strong> File <code>2_baseline.ipynb</code> + Bảng so sánh kết quả Baseline.</p></blockquote><hr><h2 id="buoi-3-toi-uu-cai-tien-hieu-nang" tabindex="-1">Buổi 3: Tối ưu &amp; Cải tiến hiệu năng <a class="header-anchor" href="#buoi-3-toi-uu-cai-tien-hieu-nang" aria-label="Permalink to &quot;Buổi 3: Tối ưu &amp; Cải tiến hiệu năng&quot;">​</a></h2><p><strong>Mục tiêu:</strong> Xử lý mất cân bằng dữ liệu và đạt mốc hiệu năng cao của bài báo <code>ishaq2021improving</code>.</p><ul><li><strong>Nhiệm vụ 1:</strong> Áp dụng kỹ thuật sinh dữ liệu nhân tạo <strong>SMOTE</strong> để cân bằng lại 2 lớp của nhãn <code>DEATH_EVENT</code>. <ul><li><em>Cảnh báo đỏ (Red Flag):</em> SMOTE tuyệt đối <strong>chỉ được áp dụng trên tập Train</strong>. Nếu bạn SMOTE cả tập Test, mô hình sẽ được đánh giá trên dữ liệu ảo, làm sai lệch kết quả lâm sàng (sẽ bị 0 điểm phần này).</li></ul></li><li><strong>Nhiệm vụ 2:</strong> Huấn luyện mô hình <strong>Extra Trees Classifier</strong> (hoặc thử nghiệm Random Forest / Gradient Boosting) trên dữ liệu đã được SMOTE. Đo lường hiệu năng trên tập Test nguyên bản.</li><li><strong>Nhiệm vụ 3:</strong> Nhóm tác giả Ishaq (2021) kết hợp SMOTE và đạt được <strong>Accuracy 92.6%</strong>. Bạn hãy tinh chỉnh mô hình (Ablation Study rút gọn với <code>n_estimators</code> hoặc thử nhiều thuật toán khác) để tiệm cận con số này.</li></ul><blockquote><p><strong>Sản phẩm bàn giao:</strong> File <code>3_improvement.ipynb</code> + Bảng so sánh mô hình Có SMOTE vs Không SMOTE.</p></blockquote><hr><h2 id="buoi-4-kha-nang-giai-thich-xai-voi-shap" tabindex="-1">Buổi 4: Khả năng giải thích (XAI) với SHAP <a class="header-anchor" href="#buoi-4-kha-nang-giai-thich-xai-voi-shap" aria-label="Permalink to &quot;Buổi 4: Khả năng giải thích (XAI) với SHAP&quot;">​</a></h2><p><strong>Mục tiêu:</strong> Chứng minh mô hình học đúng sinh lý bệnh thay vì chỉ &quot;học vẹt&quot; dữ liệu (Overfitting).</p><ul><li><strong>Nhiệm vụ 1:</strong> Sử dụng thư viện <code>shap</code> (với <code>TreeExplainer</code>) trên mô hình Extra Trees tốt nhất của bạn để tính toán giá trị SHAP cho tập Test.</li><li><strong>Nhiệm vụ 2:</strong> Vẽ biểu đồ tổng quan <code>shap.summary_plot</code> và phân tích.</li><li><strong>Nhiệm vụ 3:</strong> Đối chiếu lâm sàng. Y văn gốc chỉ ra rằng <strong>Serum Creatinine</strong> và <strong>Ejection Fraction</strong> là 2 chỉ số mang tính quyết định nhất đến sinh tử của bệnh nhân suy tim. Hãy kiểm tra xem 2 biến này có nằm ở nhóm quan trọng nhất trên biểu đồ SHAP của bạn hay không? Nếu không khớp, hãy lý giải tại sao (gợi ý: SMOTE có làm sai lệch phân bố đặc trưng gốc không?).</li></ul><blockquote><p><strong>Sản phẩm bàn giao:</strong> File <code>4_xai.ipynb</code> + Hình ảnh <code>shap_summary.png</code> + 1 đoạn bình luận đối chiếu.</p></blockquote><hr><h2 id="buoi-5-bao-cao-nghiem-thu" tabindex="-1">Buổi 5: Báo cáo &amp; Nghiệm thu <a class="header-anchor" href="#buoi-5-bao-cao-nghiem-thu" aria-label="Permalink to &quot;Buổi 5: Báo cáo &amp; Nghiệm thu&quot;">​</a></h2><p>Tổng hợp các kết quả thành một <strong>Báo cáo rút gọn</strong> (Slide hoặc PDF từ 5-10 trang) bao gồm các phần:</p><ol><li><strong>Đặt vấn đề:</strong> Bài toán, ý nghĩa lâm sàng.</li><li><strong>Y văn:</strong> Liệt kê kết quả của 2 nghiên cứu (<code>chicco2020machine</code> và <code>ishaq2021improving</code>).</li><li><strong>Phương pháp:</strong> Mô tả cách chia tập, StandardScaler, ứng dụng SMOTE.</li><li><strong>Kết quả:</strong> Bảng so sánh hiệu năng của Logistic Regression, Random Forest, và ExtraTrees+SMOTE. So sánh với số liệu của 2 nghiên cứu y văn.</li><li><strong>XAI:</strong> Chèn hình SHAP và diễn giải tầm quan trọng của các đặc trưng sinh học.</li><li><strong>Hạn chế:</strong> Chỉ ra các điểm yếu của bộ dữ liệu (cỡ mẫu nhỏ, dữ liệu cũ năm 2015, thiếu validation bên ngoài).</li></ol><hr><h2 id="tieu-chi-cham-điem-rubric-thang-100-điem" tabindex="-1">Tiêu chí chấm điểm (Rubric - Thang 100 điểm) <a class="header-anchor" href="#tieu-chi-cham-điem-rubric-thang-100-điem" aria-label="Permalink to &quot;Tiêu chí chấm điểm (Rubric - Thang 100 điểm)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Tiêu chí đánh giá</th><th style="text-align:center;">Điểm tối đa</th><th style="text-align:left;">Yêu cầu đạt chuẩn</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>1. Khám phá &amp; Tiền xử lý dữ liệu</strong></td><td style="text-align:center;"><strong>20</strong></td><td style="text-align:left;">Chia đúng Train/Test (stratified). Tránh hoàn toàn lỗi Data Leakage khi chuẩn hóa.</td></tr><tr><td style="text-align:left;"><strong>2. Tái lập Baseline</strong></td><td style="text-align:center;"><strong>20</strong></td><td style="text-align:left;">Chạy thành công Random Forest/LogReg, ra kết quả tiệm cận mốc 74% và phân tích độ lệch nếu có.</td></tr><tr><td style="text-align:left;"><strong>3. Áp dụng SMOTE &amp; Cải tiến</strong></td><td style="text-align:center;"><strong>20</strong></td><td style="text-align:left;">SMOTE <strong>chỉ áp dụng trên Train</strong>. Tăng được hiệu năng mô hình tiệm cận 90%+.</td></tr><tr><td style="text-align:left;"><strong>4. Giải thích mô hình (SHAP)</strong></td><td style="text-align:center;"><strong>20</strong></td><td style="text-align:left;">Code vẽ đúng <code>summary_plot</code>. Phân tích được vai trò của Serum Creatinine / Ejection Fraction dựa trên dữ liệu hiển thị.</td></tr><tr><td style="text-align:left;"><strong>5. Báo cáo &amp; Nhận định y khoa</strong></td><td style="text-align:center;"><strong>20</strong></td><td style="text-align:left;">Báo cáo đầy đủ 6 cấu trúc. Có khả năng nhận định trung thực các hạn chế của nghiên cứu (như cỡ mẫu nhỏ).</td></tr></tbody></table>',34)])])}const m=t(a,[["render",e]]);export{d as __pageData,m as default};
